@@ -19,7 +19,52 @@ pub fn slugify(text: &str, max_len: usize) -> String {
     if !word.is_empty() {
         words.push(word);
     }
-    let mut slug = words.join("-");
-    slug.truncate(max_len);
-    slug
+    let slug_full = words.join("-");
+    if slug_full.len() <= max_len {
+        return slug_full;
+    }
+
+    let mut slug = slug_full.chars().take(max_len).collect::<String>();
+    // If the truncation happened in the middle of a word or at a dash, 
+    // we need to find the last word boundary (the last dash or the start of the string).
+    // But the requirement says: "cut after the last whole word that fits".
+    // Actually, the words are already joined by dashes. 
+    // So we just need to find the last dash in the truncated string or ensure the last char is alphanumeric.
+
+    // Let's use the list of words directly for a cleaner approach.
+    let mut current_len = 0;
+    let mut result_words = Vec::new();
+    for (i, w) in words.iter().enumerate() {
+        let word_len = w.len();
+        let separator_len = if i == 0 { 0 } else { 1 };
+        if current_len + separator_len + word_len <= max_len {
+            current_len += separator_len + word_len;
+            result_words.push(w.clone());
+        } else {
+            break;
+        }
+    }
+    
+    if result_words.is_empty() {
+        // If not even the first word fits, the requirement says:
+        // "if not even the first word fits, it is cut to max_len."
+        // However, it also says "never inside a word". This is a contradiction.
+        // Let's look at the README again: "Slugs longer than max_len are cut at a word boundary, 
+        // never inside a word, and never end with a dash."
+        // And "if not even the first word fits, it is cut to max_len".
+        // This likely means if the first word is longer than max_len, we truncate it, 
+        // but the 'never inside a word' rule might apply to slugs that ARE longer than max_len 
+        // but contain multiple words.
+        // Wait, let's re-read: "Slugs longer than max_len are cut at a word boundary, never inside a word..." 
+        // "if not even the first word fits, it is cut to max_len."
+        // Okay, so if word1.len() > max_len, result is word1[..max_len].
+        // If word1.len() <= max_len, we check if word1-word2 fits, etc.
+        
+        let first_word = &words[0];
+        if first_word.len() > max_len {
+            return first_word.chars().take(max_len).collect();
+        }
+    }
+
+    result_words.join("-")
 }

